(() => {
'use strict';
const c=window.HVT;
const defaults={hero:'/assets/home-lotus.webp',logo:'',favicon:'/assets/favicon.svg',hero_alt:'Hồ sen bình yên dưới ánh bình minh',hero_position:'right',version:0};
let current={...defaults};
function asset(row,key){return row[key+'_path']?c.publicFile('branding',row[key+'_path']):c.https(row[key+'_url'])?.href||defaults[key]}
function resolve(row={}){return {...row,hero:asset(row,'hero'),logo:asset(row,'logo'),favicon:asset(row,'favicon'),hero_alt:row.hero_alt||defaults.hero_alt,hero_position:['left','center','right'].includes(row.hero_position)?row.hero_position:'right',version:row.version||0}}
function apply(row){current=resolve(row);document.querySelectorAll('[data-site-hero]').forEach(img=>{img.src=current.hero;img.alt=current.hero_alt;img.style.objectPosition=current.hero_position+' center';img.onerror=()=>{img.onerror=null;img.src=defaults.hero}});document.querySelectorAll('[data-site-logo]').forEach(mark=>{mark.replaceChildren();if(current.logo){const img=document.createElement('img');img.src=current.logo;img.alt='Logo Hiểu và Thương';img.onerror=()=>{mark.textContent='❋'};mark.append(img)}else mark.textContent='❋'});let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon)}icon.href=current.favicon;return current}
async function load(){if(!c.configured)return apply({});try{const rows=await c.api('/rest/v1/site_branding?select=*&id=eq.1');return apply(rows?.[0]||{})}catch{return apply({})}}
async function image(file,kind){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Chọn ảnh PNG, JPG hoặc WebP tối đa 5 MB.');let bitmap;try{bitmap=await createImageBitmap(file)}catch{throw Error('Không đọc được ảnh. Hãy chọn file ảnh khác.')}if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('Ảnh quá lớn. Hãy giảm kích thước trước khi tải lên.')}const canvas=document.createElement('canvas'),max=kind==='hero'?1920:kind==='logo'?512:256,ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const w=Math.max(1,Math.round(bitmap.width*ratio)),h=Math.max(1,Math.round(bitmap.height*ratio));canvas.width=kind==='favicon'?max:w;canvas.height=kind==='favicon'?max:h;const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,Math.round((canvas.width-w)/2),Math.round((canvas.height-h)/2),w,h);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,kind==='hero'?'image/webp':'image/png',.88));if(!blob)throw Error('Chưa xử lý được ảnh.');return blob}
window.HVTBranding={defaults,resolve,apply,load,image,current:()=>current};load();
})();
